module mul8s(input clk, input rst_n, input start, input [7:0] a, input [7:0] b,
             output reg busy, output reg done, output reg [15:0] p);
  reg [15:0] w; reg [7:0] m; reg [2:0] cnt;
  wire [8:0] sum = w[0] ? ({1'b0, w[15:8]} + {1'b0, m}) : {1'b0, w[15:8]};
  wire [15:0] nw = {sum, w[7:1]};
  wire last = busy & (cnt == 3'd7);
  always @(posedge clk) begin
    if (!rst_n) begin
      busy <= 1'b0; done <= 1'b0; p <= 16'd0; cnt <= 3'd0;
    end else begin
      done <= last;
      if (busy) begin
        w <= nw;
        cnt <= cnt + 3'd1;
        if (last) begin busy <= 1'b0; p <= nw; end
      end else if (start) begin
        busy <= 1'b1; w <= {8'd0, b}; m <= a;
      end
    end
  end
endmodule
